<?php
use GroupShop\Manager\{Stores,Catalog,SharedTaxonomies,Collections};
if (!defined('WP_CLI')||!WP_CLI||wp_get_environment_type()!=='local'||wp_parse_url(get_home_url(Stores::main_id()),PHP_URL_HOST)!=='localhost'||(int)wp_parse_url(get_home_url(Stores::main_id()),PHP_URL_PORT)!==18087) { throw new RuntimeException('Local isolated QA only'); }
wp_set_current_user(get_user_by('login','gsm-admin')->ID);
$checks=[]; $assert=static function ($ok,$name) use (&$checks): void { if (!$ok) { throw new RuntimeException('FAIL: '.$name); } $checks[]=$name; };
$main=Stores::main_id(); $a=(int)get_site_by_path(get_network()->domain,'/brand-a/')->blog_id; $b=(int)get_site_by_path(get_network()->domain,'/brand-b/')->blog_id;
$suffix=bin2hex(random_bytes(3));
$local=static fn($store,$source,$tax)=>Stores::within($store,static function () use ($source,$tax): int { $ids=get_terms(['taxonomy'=>$tax,'hide_empty'=>false,'fields'=>'ids','meta_query'=>[['key'=>'_gsm_shared_source','value'=>$source]]]); return count($ids)===1?(int)$ids[0]:0; });
$parent=wp_insert_term('QA Shared Parent '.$suffix,'product_cat')['term_id'];
$category=wp_insert_term('QA Shared Child '.$suffix,'product_cat',['parent'=>$parent,'description'=>'Shared description'])['term_id'];
$tag=wp_insert_term('QA Shared Tag '.$suffix,'product_tag')['term_id'];
update_term_meta($category,'order',7);
require_once ABSPATH.'wp-admin/includes/image.php';
$file=wp_upload_bits('shared-taxonomy-'.$suffix.'.png',null,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aWQAAAABJRU5ErkJggg=='));
$image=(int)wp_insert_attachment(['post_title'=>'QA Shared Category Image','post_mime_type'=>'image/png','post_status'=>'inherit'],$file['file']);
wp_update_attachment_metadata($image,wp_generate_attachment_metadata($image,$file['file'])); update_term_meta($category,'thumbnail_id',$image);
SharedTaxonomies::reconcile();
$ca=$local($a,$category,'product_cat'); $cb=$local($b,$category,'product_cat'); $ta=$local($a,$tag,'product_tag');
$assert($ca>0&&$cb>0&&$ta>0,'Main native categories and tags project to every active store');
$assert(Stores::within($a,fn()=>get_term($ca,'product_cat')->parent)===$local($a,$parent,'product_cat'),'Category hierarchy uses the correct local parent ID');
$assert(Stores::within($a,fn()=>get_term_meta($ca,'order',true))=='7','Native category ordering projects from the authority');
$assert(Stores::within($a,fn()=>str_contains((string)wp_get_attachment_url((int)get_term_meta($ca,'thumbnail_id',true)),'/sites/'.$a.'/')),'Shared category image is copied into the target store media library');
$image_a=Stores::within($a,fn()=>(int)get_term_meta($ca,'thumbnail_id',true)); SharedTaxonomies::reconcile(true);
$assert(Stores::within($a,fn()=>(int)get_term_meta($ca,'thumbnail_id',true))===$image_a,'Repeated projection reuses the existing imported category image');
$p=new WC_Product_Simple(); $p->set_name('QA Shared Product '.$suffix); $p->set_regular_price('10'); $p->set_status('publish'); $p->set_category_ids([$category]); $p->set_tag_ids([$tag]); $source=$p->save();
$pa=Catalog::publish($source,$a,Catalog::FIELDS); $pb=Catalog::publish($source,$b,Catalog::FIELDS);
$assert(Stores::within($a,fn()=>wc_get_product($pa)->get_category_ids())===[$ca]&&Stores::within($a,fn()=>wc_get_product($pa)->get_tag_ids())===[$ta],'New editions use the single source product classification');
$assert(Stores::within($a,fn()=>get_post_status($pa))==='draft','Taxonomy synchronization does not publish a draft edition');
$collection=Collections::save_collection($a,0,['name'=>'QA Shared Collection '.$suffix,'mode'=>'rule','categories'=>[$ca],'enabled'=>'1']);
$assert(Stores::within($a,fn()=>has_term($collection,'product_cat',$pa)),'Store-local collections remain compatible with shared classification');
wp_update_term($category,'product_cat',['name'=>'QA Shared Renamed '.$suffix,'slug'=>'shared-renamed-'.$suffix,'description'=>'Updated globally','parent'=>0]);
wp_update_term($tag,'product_tag',['name'=>'QA Shared Tag Renamed '.$suffix]); SharedTaxonomies::reconcile();
$assert($local($a,$category,'product_cat')===$ca&&$local($b,$category,'product_cat')===$cb,'Renaming preserves local term IDs and product relationships');
$assert(Stores::within($a,fn()=>get_term($ca,'product_cat')->name)==='QA Shared Renamed '.$suffix&&Stores::within($b,fn()=>get_term($cb,'product_cat')->description)==='Updated globally','Native main-site edits change all storefront terms');
$assert(Stores::within($a,fn()=>get_term($ca,'product_cat')->parent)===0,'Parent edits propagate globally');
$assert(Stores::within($a,fn()=>get_term($ta,'product_tag')->name)==='QA Shared Tag Renamed '.$suffix,'Tag edits propagate globally');
$collection_slug=Stores::within($a,fn()=>get_term($collection,'product_cat')->slug);
$assert(!get_term_by('slug',$collection_slug,'product_cat'),'A store collection is not promoted into the main vocabulary');
$assert(Stores::within($a,fn()=>!current_user_can('manage_product_terms')&&!current_user_can('edit_product_terms')&&!current_user_can('delete_product_terms')),'Even network administrators cannot edit projected terms through child-site native capabilities');
$result=Stores::within($a,fn()=>wp_insert_term('Forbidden local term '.$suffix,'product_tag'));
$assert(is_wp_error($result),'Child-site native term creation rejects divergent local vocabulary');
$assert(current_user_can('manage_product_terms'),'Main native taxonomy administration remains available');
$other=wp_insert_term('QA Shared Other '.$suffix,'product_cat')['term_id']; SharedTaxonomies::reconcile(); $oa=$local($a,$other,'product_cat'); $ob=$local($b,$other,'product_cat');
wp_set_object_terms($source,[$other],'product_cat'); wp_set_object_terms($source,[],'product_tag'); SharedTaxonomies::reconcile();
$assert(Stores::within($a,fn()=>wc_get_product($pa)->get_category_ids())===[$oa]&&Stores::within($b,fn()=>wc_get_product($pb)->get_category_ids())===[$ob],'Main product assignment changes apply to every mapped edition');
$assert(Stores::within($a,fn()=>wc_get_product($pa)->get_tag_ids())===[],'Removing source tags clears all edition tags');
Stores::within($a,static function () use ($pa,$ca): void { wp_set_object_terms($pa,[$ca],'product_cat'); });
$assert(Stores::within($a,fn()=>wc_get_product($pa)->get_category_ids())===[$oa],'Mapped edition cannot diverge from source classification');
$before=Stores::within($a,fn()=>get_option('gsm_collections'));
SharedTaxonomies::reconcile(true);
$assert(Stores::within($a,fn()=>get_option('gsm_collections'))===$before,'Idempotent reconciliation preserves collection rules');
// Missing shared conditions must not broaden an existing collection to the entire catalog.
wp_delete_term($category,'product_cat'); SharedTaxonomies::reconcile();
$assert(!Stores::within($a,fn()=>term_exists($ca,'product_cat'))&&!Stores::within($b,fn()=>term_exists($cb,'product_cat')),'Deleting an authority term removes all projections');
$rule=Stores::within($a,fn()=>Collections::collections()[$collection]);
$assert(!$rule['enabled']&&!empty($rule['needs_review']),'Deleting a rule condition disables the collection pending correction');
$assert(Stores::within($a,fn()=>term_exists($collection,'product_cat')),'Shared vocabulary deletion preserves store-local collection archives');
$assert(get_current_blog_id()===$main,'Shared synchronization restores original store context');
$legacy=SharedTaxonomies::local_collection(static fn()=>Stores::within($a,static function () use ($suffix): int { return (int)wp_insert_term('QA Legacy Unique '.$suffix,'product_cat',['slug'=>'qa-legacy-unique-'.$suffix])['term_id']; }));
$rules_before=Stores::within($a,fn()=>Collections::collections());
update_blog_option($a,'gsm_shared_taxonomy_revision',0); SharedTaxonomies::reconcile();
$imported=get_term_by('slug','qa-legacy-unique-'.$suffix,'product_cat');
$assert($imported&&$local($a,(int)$imported->term_id,'product_cat')===$legacy,'First consolidation imports unique legacy vocabulary while preserving original local term IDs');
$assert(Stores::within($a,fn()=>Collections::collections())===$rules_before,'Legacy vocabulary consolidation preserves existing collection definitions');
// A newly created store receives the global vocabulary without a second editing authority.
$existing=get_site_by_path(get_network()->domain,'/qa-shared-store/');
$new=$existing&&(int)$existing->blog_id!==$main?(int)$existing->blog_id:Stores::create('QA Shared Store','qa-shared-store');
SharedTaxonomies::reconcile();
$assert($local($new,$other,'product_cat')>0&&$local($new,$tag,'product_tag')>0,'New stores automatically receive the shared native vocabulary');
$assert(Stores::within($new,fn()=>count(Collections::terms('product_cat')))===count(Collections::terms('product_cat')),'New stores have exactly the same shared category vocabulary');
$assert(Stores::within($new,fn()=>(int)get_term_meta((int)get_option('default_product_cat'),'_gsm_shared_source',true))===(int)get_option('default_product_cat'),'New store default category maps to the authority default');
echo wp_json_encode(['version'=>GSM_VERSION,'passed'=>count($checks),'checks'=>$checks,'fixtures'=>['main'=>$main,'a'=>$a,'b'=>$b,'new'=>$new,'source'=>$source,'edition'=>$pa,'category'=>$other,'tag'=>$tag,'local_category'=>$oa,'collection'=>$collection]],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)."\n";
